insert into public.infographic_templates
  (slug, title, domain, tags, engine, visual_type, dsl, card_dsl, variables, theme_tokens, is_public)
values
  ('rbf-sandbox-settlement-flow', 'RBF Sandbox Settlement Flow', 'executive_regulatory'::infographic_domain, array['dimau_capital','rbf','remittance']::text[], 'antv', 'Multi-stage sequence + compliance KPIs', '{"template":"sequence-ascending-steps","width":960,"height":540,"themeConfig":{"palette":["#00E5FF","#FF5A36","#F5B041","#7C8CFF","#3DDC97"]},"data":{"title":"{{corridor_name}}","desc":"{{sandbox_phase}}","sequences":[{"label":"Settlement","desc":"{{settlement_speed_sec}}"},{"label":"Fee cut","desc":"{{fee_reduction_pct}}"},{"label":"AML / KYC","desc":"{{kyc_pass_rate}}"},{"label":"Reserve","desc":"{{reserve_backing_fjd}}"}]}}'::jsonb, null, '[{"name":"corridor_name","type":"string","required":false,"default":"UK → Suva Instant Remittance & Settlement","description":"Payment corridor shown as the headline"},{"name":"settlement_speed_sec","type":"string","required":false,"default":"2.4s","description":"Average settlement time"},{"name":"fee_reduction_pct","type":"string","required":false,"default":"78%","description":"Fee reduction against the market"},{"name":"kyc_pass_rate","type":"string","required":false,"default":"99.4% Automated AML/KYC","description":"Automated compliance pass rate"},{"name":"reserve_backing_fjd","type":"string","required":false,"default":"FJD $1.25M Ring-Fenced","description":"Reserve held against balances"},{"name":"sandbox_phase","type":"string","required":false,"default":"Phase 2: Live Cohort Testing","description":"Current RBF sandbox stage"}]'::jsonb, '{"obsidian":"#07090E","coral":"#FF5A36","lagoon":"#00E5FF","gold":"#F5B041","white":"#F8FAFC"}'::jsonb, true),
  ('sota-kece-community-pulse', 'Sota Kece Community Pulse', 'social_community'::infographic_domain, array['sota_kece','sevu']::text[], 'antv', 'Radial hub + share card', '{"template":"list-sector-plain-text","width":960,"height":640,"themeConfig":{"palette":["#00E5FF","#FF5A36","#F5B041","#7C8CFF","#3DDC97"]},"data":{"title":"{{province_hub}}","items":[{"label":"Creators {{active_creators}}"},{"label":"Vibe {{daily_vibe_score}}"},{"label":"Sevu tips {{sevu_tips_volume_fjd}}"},{"label":"{{top_cultural_tag}}"}]}}'::jsonb, '{"width":1200,"height":630,"tree":{"type":"div","props":{"style":{"display":"flex","flexDirection":"column","justifyContent":"space-between","width":1088,"height":518,"padding":56,"backgroundColor":"#07090E","backgroundImage":"radial-gradient(circle at 85% 15%, rgba(0,229,255,0.28), transparent 45%), radial-gradient(circle at 10% 95%, rgba(255,90,54,0.25), transparent 50%)","color":"#F8FAFC","fontFamily":"Inter"},"children":[{"type":"div","props":{"style":{"display":"flex","flexDirection":"column"},"children":[{"type":"div","props":{"style":{"display":"flex","fontSize":30,"color":"#00E5FF","letterSpacing":1},"children":"{{province_hub}}"}},{"type":"div","props":{"style":{"display":"flex","fontSize":76,"fontWeight":700,"marginTop":12},"children":"{{top_cultural_tag}}"}}]}},{"type":"div","props":{"style":{"display":"flex","justifyContent":"space-between"},"children":[{"type":"div","props":{"style":{"display":"flex","flexDirection":"column","padding":"20px 24px","borderRadius":20,"backgroundColor":"rgba(248,250,252,0.06)","border":"1px solid rgba(248,250,252,0.12)","width":300},"children":[{"type":"div","props":{"style":{"display":"flex","fontSize":22,"color":"rgba(248,250,252,0.6)"},"children":"Creators"}},{"type":"div","props":{"style":{"display":"flex","fontSize":40,"fontWeight":700,"color":"#F8FAFC","marginTop":6},"children":"{{active_creators}}"}}]}},{"type":"div","props":{"style":{"display":"flex","flexDirection":"column","padding":"20px 24px","borderRadius":20,"backgroundColor":"rgba(248,250,252,0.06)","border":"1px solid rgba(248,250,252,0.12)","width":300},"children":[{"type":"div","props":{"style":{"display":"flex","fontSize":22,"color":"rgba(248,250,252,0.6)"},"children":"Vibe"}},{"type":"div","props":{"style":{"display":"flex","fontSize":40,"fontWeight":700,"color":"#00E5FF","marginTop":6},"children":"{{daily_vibe_score}}"}}]}},{"type":"div","props":{"style":{"display":"flex","flexDirection":"column","padding":"20px 24px","borderRadius":20,"backgroundColor":"rgba(248,250,252,0.06)","border":"1px solid rgba(248,250,252,0.12)","width":300},"children":[{"type":"div","props":{"style":{"display":"flex","fontSize":22,"color":"rgba(248,250,252,0.6)"},"children":"Sevu tips"}},{"type":"div","props":{"style":{"display":"flex","fontSize":40,"fontWeight":700,"color":"#F5B041","marginTop":6},"children":"{{sevu_tips_volume_fjd}}"}}]}}]}}]}}}'::jsonb, '[{"name":"province_hub","type":"string","required":false,"default":"Rewa / Suva Central","description":"Province or hub the pulse is for"},{"name":"active_creators","type":"string","required":false,"default":"14,820","description":"Active creators"},{"name":"daily_vibe_score","type":"string","required":false,"default":"94% Positive","description":"Sentiment score for the day"},{"name":"top_cultural_tag","type":"string","required":false,"default":"#VitiLevuCreators","description":"Top trending tag"},{"name":"sevu_tips_volume_fjd","type":"string","required":false,"default":"FJD $42,900","description":"Tips sent through Sevu"}]'::jsonb, '{"obsidian":"#07090E","coral":"#FF5A36","lagoon":"#00E5FF","gold":"#F5B041","white":"#F8FAFC"}'::jsonb, true),
  ('pacific-backhaul-node-map', 'Pacific Backhaul Node Map', 'connectivity_telecom'::infographic_domain, array['vanua_os','starlink','esim']::text[], 'antv', 'Network telemetry matrix', '{"template":"compare-quadrant-quarter-simple-card","width":960,"height":600,"themeConfig":{"palette":["#00E5FF","#FF5A36","#F5B041","#7C8CFF","#3DDC97"]},"data":{"title":"{{primary_uplink}}","items":[{"label":"Island nodes","desc":"{{active_island_nodes}}"},{"label":"Latency","desc":"{{avg_latency_ms}}"},{"label":"eSIM sessions","desc":"{{esim_active_sessions}}"},{"label":"Power","desc":"{{grid_autonomy_pct}}"}]}}'::jsonb, null, '[{"name":"primary_uplink","type":"string","required":false,"default":"Starlink LEO Gateway - Nasese","description":"Main uplink"},{"name":"active_island_nodes","type":"string","required":false,"default":"18 Vanua Mesh Nodes","description":"Live island nodes"},{"name":"avg_latency_ms","type":"string","required":false,"default":"34ms","description":"Average latency"},{"name":"esim_active_sessions","type":"string","required":false,"default":"3,410 Active Roaming Profiles","description":"Active eSIM sessions"},{"name":"grid_autonomy_pct","type":"string","required":false,"default":"100% Solar + Battery Backed","description":"Off-grid power share"}]'::jsonb, '{"obsidian":"#07090E","coral":"#FF5A36","lagoon":"#00E5FF","gold":"#F5B041","white":"#F8FAFC"}'::jsonb, true),
  ('debt-freedom-trajectory', 'Debt Freedom Trajectory', 'fintech_capital'::infographic_domain, array['mydebtcalculator']::text[], 'antv', 'Before / after comparison', '{"template":"compare-binary-horizontal-badge-card-vs","width":960,"height":540,"themeConfig":{"palette":["#00E5FF","#FF5A36","#F5B041","#7C8CFF","#3DDC97"]},"data":{"title":"{{total_debt_fjd}}","desc":"{{strategy_mode}}","compares":[{"label":"Before","children":[{"label":"Minimum payments","desc":"Interest keeps growing"}]},{"label":"After","children":[{"label":"{{months_shaved}}","desc":"{{interest_saved_fjd}}"},{"label":"Debt free","desc":"{{debt_free_date}}"}]}]}}'::jsonb, null, '[{"name":"total_debt_fjd","type":"string","required":false,"default":"FJD $18,500","description":"Total debt being cleared"},{"name":"months_shaved","type":"string","required":false,"default":"19 Months Faster","description":"Time saved against minimum payments"},{"name":"interest_saved_fjd","type":"string","required":false,"default":"FJD $4,120 Saved","description":"Interest saved"},{"name":"debt_free_date","type":"string","required":false,"default":"August 2028","description":"Projected debt-free date"},{"name":"strategy_mode","type":"string","required":false,"default":"Avalanche High-APR Priority","description":"Repayment strategy"}]'::jsonb, '{"obsidian":"#07090E","coral":"#FF5A36","lagoon":"#00E5FF","gold":"#F5B041","white":"#F8FAFC"}'::jsonb, true)
